class Solution {
public:
    int subsequenceCount(vector<int>& nums) {
        const int MOD = 1000000007;
        long long even = 1, odd = 0;
        for (int x : nums) {
            long long nextEven = (even + ((x & 1) ? odd : even)) % MOD;
            long long nextOdd = (odd + ((x & 1) ? even : odd)) % MOD;
            even = nextEven;
            odd = nextOdd;
        }
        return static_cast<int>(odd);
    }
};
